    "entityType": "author",
    "direction": "defToName",
    "difficulty": "facile",
    "prompt": "« Cette personne refuse de choisir entre deux positions extrêmes : pour lui, la société n'est ni une réalité supérieure aux individus, ni une simple fiction sans consistance propre. La société existe précisément dans les interactions entre les personnes : chaque fois que des individus entrent en relation, il y a société. Il étudie ainsi les formes récurrentes de ces interactions (la domination, le conflit, l'échange) plutôt que leur contenu particulier. Dans sa Philosophie de l'argent, il montre comment l'argent transforme à la fois la liberté individuelle et les liens entre les personnes. Son influence directe sur Robert Park, qui fut son étudiant à Berlin, en fait une figure importante à l'origine de l'école de sociologie de Chicago. »\n\nCette description correspond à :",
